INSERT OR IGNORE INTO "site_setting" ("id", "siteTitle", "ownerName", "heroGreeting", "heroRoles", "heroTagline", "avatarUrl", "aboutTitle", "aboutText", "resumeUrl", "email", "phone", "location", "availability", "primaryColor", "accentColor", "marqueeText", "footerText", "updatedAt") VALUES ('main', 'MD Salahuddin — Creative Full-Stack Developer', 'MD Salahuddin', 'Hello, I''m', 'Full-Stack Developer, Next.js Specialist, UI Animation Lover, Open-Source Contributor', 'I craft immersive digital experiences where engineering meets art. Every pixel moves with purpose, every interaction tells a story. Let''s build something people remember.', '', 'Crafting digital *magic* since day one', 'I''m a passionate developer & designer who believes great software should feel alive. For over 5 years I''ve been building web products for startups and agencies across the globe — from silky-smooth marketing sites to complex data platforms.

My sweet spot lives at the intersection of code and motion: interfaces that respond, flow and delight. When I''m not shipping features, you''ll find me sketching interface ideas, contributing to open source, or exploring generative art.', '', 'hello@mdsalahuddin.dev', '+880 1700 000000', 'Dhaka, Bangladesh', 'Available for freelance', '#8b5cf6', '#d946ef', 'Creative Development, UI/UX Design, Motion Design, Web Animations, React & Next.js, Brand Identity, Open Source, Performance', 'Designed & built with passion', '2026-10-27T00:29:06.557Z');

