-- project (6 rows)
INSERT OR IGNORE INTO "project" ("id", "title", "description", "imageUrl", "tags", "githubUrl", "liveUrl", "featured", "order", "createdAt") VALUES ('cmvpx7u41000dy01ni9xlj8ji', 'Nebula — SaaS Analytics Platform', 'A real-time analytics dashboard processing 2M+ events daily. Built with Next.js, WebSockets and a custom charting engine with buttery 60fps animations, dark-mode design system and role-based access.', 'https://picsum.photos/seed/nebula42/960/640', 'Next.js, TypeScript, WebSockets, Prisma', 'https://github.com', 'https://example.com', 1, 1, '2026-10-27T00:24:04.000Z');
INSERT OR IGNORE INTO "project" ("id", "title", "description", "imageUrl", "tags", "githubUrl", "liveUrl", "featured", "order", "createdAt") VALUES ('cmvpx7u41000ey01ns00u0lhp', 'Lumen — Immersive Agency Site', 'An award-style agency website with scroll-driven storytelling, WebGL hero shaders and page transitions. Scored 98 on Lighthouse while shipping 40+ bespoke animations.', 'https://picsum.photos/seed/lumen7/960/640', 'React, GLSL, GSAP, Framer Motion', 'https://github.com', 'https://example.com', 1, 2, '2026-10-27T00:24:04.000Z');
INSERT OR IGNORE INTO "project" ("id", "title", "description", "imageUrl", "tags", "githubUrl", "liveUrl", "featured", "order", "createdAt") VALUES ('cmvpx7u41000fy01nyxbswoxw', 'Pulse — Team Chat App', 'Realtime team messaging with threads, presence indicators, optimistic UI and offline sync. Handles 10k concurrent connections on a pocket-friendly infra budget.', 'https://picsum.photos/seed/pulse19/960/640', 'Next.js, Socket.io, Redis, Zustand', 'https://github.com', '', 0, 3, '2026-10-27T00:24:04.000Z');
INSERT OR IGNORE INTO "project" ("id", "title", "description", "imageUrl", "tags", "githubUrl", "liveUrl", "featured", "order", "createdAt") VALUES ('cmvpx7u41000gy01njfxe0se3', 'Atlas — Travel Journal PWA', 'An offline-first progressive web app for globetrotters. Map-based timeline, photo stories, background sync and app-like feel with home-screen install support.', 'https://picsum.photos/seed/atlas88/960/640', 'PWA, Mapbox, IndexedDB, Workbox', '', 'https://example.com', 0, 4, '2026-10-27T00:24:04.000Z');
INSERT OR IGNORE INTO "project" ("id", "title", "description", "imageUrl", "tags", "githubUrl", "liveUrl", "featured", "order", "createdAt") VALUES ('cmvpx7u42000hy01nqxolehrb', 'Forge — Headless Commerce Starter', 'A blazing-fast storefront starter for headless e-commerce. Edge-rendered product pages, animated cart drawer, one-click checkout flow and a 100/100 SEO score.', 'https://picsum.photos/seed/forge55/960/640', 'Next.js, Stripe, Edge Runtime', 'https://github.com', 'https://example.com', 0, 5, '2026-10-27T00:24:04.000Z');
INSERT OR IGNORE INTO "project" ("id", "title", "description", "imageUrl", "tags", "githubUrl", "liveUrl", "featured", "order", "createdAt") VALUES ('cmvpx7u42000iy01n6j6jtt7c', 'Echo — AI Writing Companion', 'A distraction-free editor with AI-assisted rewriting, animated suggestion cards and markdown export. Streams tokens with typewriter rendering for a magical feel.', 'https://picsum.photos/seed/echo23/960/640', 'React, LLM API, Streaming, Tiptap', 'https://github.com', '', 0, 6, '2026-10-27T00:24:04.000Z');

-- experience (3 rows)
INSERT OR IGNORE INTO "experience" ("id", "role", "company", "period", "description", "current", "order", "createdAt") VALUES ('cmvpx7u43000jy01n6zlgk738', 'Senior Full-Stack Engineer', 'Stellar Labs', '2023 — Present', 'Leading the frontend architecture of a multi-tenant SaaS platform. Shipped a design system used by 4 products, cut bundle size by 45% and mentor a team of five engineers.', 1, 1, '2026-10-27T00:24:04.000Z');
INSERT OR IGNORE INTO "experience" ("id", "role", "company", "period", "description", "current", "order", "createdAt") VALUES ('cmvpx7u43000ky01n5lzl7mz5', 'Frontend Engineer', 'PixelForge Studio', '2021 — 2023', 'Built 15+ marketing sites and web apps for international clients. Owned motion design and interaction quality across projects, winning two site-of-the-day awards.', 0, 2, '2026-10-27T00:24:04.000Z');
INSERT OR IGNORE INTO "experience" ("id", "role", "company", "period", "description", "current", "order", "createdAt") VALUES ('cmvpx7u43000ly01n5j25wtvr', 'Junior Web Developer', 'CodeCraft Agency', '2019 — 2021', 'Cut my teeth building responsive WordPress and React sites. Learned to sweat the details — accessibility, performance budgets and pixel-perfect delivery.', 0, 3, '2026-10-27T00:24:04.000Z');

-- education (2 rows)
INSERT OR IGNORE INTO "education" ("id", "degree", "institution", "period", "description", "order", "createdAt") VALUES ('cmvpx7u44000my01npczdkk72', 'BSc in Computer Science & Engineering', 'University of Dhaka', '2015 — 2019', 'Graduated with distinction. Thesis on perceptual performance of animated web interfaces. Led the programming club and organised two national hackathons.', 1, '2026-10-27T00:24:04.000Z');
INSERT OR IGNORE INTO "education" ("id", "degree", "institution", "period", "description", "order", "createdAt") VALUES ('cmvpx7u44000ny01nz0e5ms28', 'Diploma in Interactive Design', 'Bangladesh Design Institute', '2014 — 2015', 'Foundation year in visual design, typography and color theory — the secret sauce behind my developer-designer hybrid skill set.', 2, '2026-10-27T00:24:04.000Z');

-- service (4 rows)
INSERT OR IGNORE INTO "service" ("id", "title", "description", "icon", "order", "createdAt") VALUES ('cmvpx7u45000oy01nnfwgqaft', 'Web Development', 'End-to-end development of fast, scalable web apps — from architecture and APIs to pixel-perfect responsive frontends that pass Core Web Vitals with flying colors.', 'Code2', 1, '2026-10-27T00:24:04.000Z');
INSERT OR IGNORE INTO "service" ("id", "title", "description", "icon", "order", "createdAt") VALUES ('cmvpx7u45000py01njxo5q893', 'UI/UX Design', 'Interfaces that feel effortless. Research, wireframes, high-fidelity prototypes and design systems that keep your product consistent as it grows.', 'Palette', 2, '2026-10-27T00:24:04.000Z');
INSERT OR IGNORE INTO "service" ("id", "title", "description", "icon", "order", "createdAt") VALUES ('cmvpx7u45000qy01njt32hedb', 'Motion & Interaction', 'Scroll choreography, micro-interactions, page transitions and WebGL moments — the details that make visitors say wow and remember your brand.', 'Sparkles', 3, '2026-10-27T00:24:04.000Z');
INSERT OR IGNORE INTO "service" ("id", "title", "description", "icon", "order", "createdAt") VALUES ('cmvpx7u45000ry01nddbl1h4n', 'Performance & SEO', 'Audits and hands-on optimization: bundle diets, edge caching, structured data and accessibility passes that lift both rankings and conversions.', 'Rocket', 4, '2026-10-27T00:24:04.000Z');

-- testimonial (4 rows)
INSERT OR IGNORE INTO "testimonial" ("id", "name", "role", "company", "content", "avatarUrl", "rating", "order", "createdAt") VALUES ('cmvpx7u46000sy01nkcwr6ge2', 'Sarah Mitchell', 'Product Lead', 'Stellar Labs', 'Salahuddin is the rare engineer who thinks like a designer. He rebuilt our dashboard and our users literally emailed us to say it felt magical. Delivery was early, quality was exceptional.', '', 5, 1, '2026-10-27T00:24:04.000Z');
INSERT OR IGNORE INTO "testimonial" ("id", "name", "role", "company", "content", "avatarUrl", "rating", "order", "createdAt") VALUES ('cmvpx7u46000ty01nuj4tgzk3', 'James Okafor', 'Founder', 'Lumen Agency', 'Every agency promises ''premium''. Salahuddin actually delivers it — obsessive attention to animation timing, loading states, the works. Our site won an award the month it launched.', '', 5, 2, '2026-10-27T00:24:04.000Z');
INSERT OR IGNORE INTO "testimonial" ("id", "name", "role", "company", "content", "avatarUrl", "rating", "order", "createdAt") VALUES ('cmvpx7u46000uy01n16wy1fxk', 'Nadia Chen', 'CTO', 'PulseChat', 'He took a vague idea and turned it into a realtime app our investors called ''deceptively simple''. Communication was crisp, architecture was clean, code was a joy to review.', '', 5, 3, '2026-10-27T00:24:04.000Z');
INSERT OR IGNORE INTO "testimonial" ("id", "name", "role", "company", "content", "avatarUrl", "rating", "order", "createdAt") VALUES ('cmvpx7u46000vy01nlipnv84h', 'Tomás Rivera', 'Marketing Director', 'Atlas Travel', 'Our engagement doubled after the redesign. The site doesn''t just look animated — it converts. Salahuddin understood business goals first, then made the tech serve them.', '', 5, 4, '2026-10-27T00:24:04.000Z');

